+  <script>
+    (() => {
+      const root = document.documentElement;
+      const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
+      let targetX = 0;
+      let targetY = 0;
+      let currentX = 0;
+      let currentY = 0;
+      let frame = 0;
+
+      const render = () => {
+        currentX += (targetX - currentX) * 0.085;
+        currentY += (targetY - currentY) * 0.085;
+
+        root.style.setProperty('--scene-x', `${(currentX * 9).toFixed(2)}px`);
+        root.style.setProperty('--scene-y', `${(currentY * 6).toFixed(2)}px`);
+        root.style.setProperty('--tilt-x', `${(currentY * -1.45).toFixed(2)}deg`);
+        root.style.setProperty('--tilt-y', `${(currentX * 2.4).toFixed(2)}deg`);
+        root.style.setProperty('--steam-x', `${(currentX * -11).toFixed(2)}px`);
+        root.style.setProperty('--steam-y', `${(currentY * -3).toFixed(2)}px`);
+        root.style.setProperty('--steam-skew', `${(currentX * -1.5).toFixed(2)}deg`);
+        root.style.setProperty('--glow-x', `${(50 + currentX * 5).toFixed(2)}%`);
+        root.style.setProperty('--glow-y', `${(56 + currentY * 2.5).toFixed(2)}%`);
+
+        if (Math.abs(targetX - currentX) > 0.001 || Math.abs(targetY - currentY) > 0.001) {
+          frame = requestAnimationFrame(render);
+        } else {
+          frame = 0;
+        }
+      };
+
+      const requestRender = () => {
+        if (!frame) frame = requestAnimationFrame(render);
+      };
+
+      const onPointerMove = (event) => {
+        if (motionQuery.matches) return;
+        targetX = Math.max(-1, Math.min(1, (event.clientX / window.innerWidth - .5) * 2));
+        targetY = Math.max(-1, Math.min(1, (event.clientY / window.innerHeight - .5) * 2));
+        requestRender();
+      };
+
+      const settle = () => {
+        targetX = 0;
+        targetY = 0;
+        requestRender();
+      };
+
+      const honorMotionPreference = () => {
+        if (motionQuery.matches) {
+          targetX = 0;
+          targetY = 0;
+          currentX = 0;
+          currentY = 0;
+          if (frame) cancelAnimationFrame(frame);
+          frame = 0;
+          root.style.removeProperty('--scene-x');
+          root.style.removeProperty('--scene-y');
+          root.style.removeProperty('--tilt-x');
+          root.style.removeProperty('--tilt-y');
+          root.style.removeProperty('--steam-x');
+          root.style.removeProperty('--steam-y');
+          root.style.removeProperty('--steam-skew');
+          root.style.removeProperty('--glow-x');
+          root.style.removeProperty('--glow-y');
+        }
